import fitz
d=fitz.open('run1c_sensitivity_prelim_zoomIn1_nov.pdf')
p=d[0]
for i,dr in enumerate(p.get_drawings()):
    if dr['type']=='s' and dr.get('color')==(0,0,0):
        npts=sum(len(it) for it in dr['items'])
        if npts<=5:
            for it in dr['items']:
                print(i, it)
